list_tax_codes.code:
use WebCommander\Sdk\Resources\TaxCodes\TaxCodes;

$response = TaxCodes::listTaxCodes($client, ['limit' => 20]);

foreach ($response->map['tax_codes'] as $taxCode) {
    echo $taxCode['id'], ' ', $taxCode['name'], ' ', $taxCode['rate'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' tax codes in total', PHP_EOL;

create_tax_code.code:
use WebCommander\Sdk\Resources\TaxCodes\TaxCodes;

$response = TaxCodes::createTaxCode($client, [
    'tax_code' => [
        'name' => 'LUXURY', 'label' => 'Luxury goods', 'description' => 'Higher rate for luxury goods',
        'rate' => 15.0, 'resolver_type' => 'flat', 'priority' => 1,
    ],
]);

echo $response->map['tax_code']['id'], PHP_EOL;
